# -*- coding: utf-8 -*-
"""Türkçe metin işlemleri: Türkçe kurallarla küçük/büyük harfe çevirme ve Türk alfabesine göre sıralama."""

_TR_ALPHABET = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
_ALPHABET_INDEX = {ch: i for i, ch in enumerate(_TR_ALPHABET)}

_DIGITS = "0123456789"
_DIGIT_RANK = {ch: i for i, ch in enumerate(_DIGITS)}

# Küçük harflerden büyük harflere (Türkçe kuralları)
_TO_UPPER = {
    "i": "İ",  # dotless i -> dotted uppercase I
    "ı": "I",  # dotted i -> uppercase I
}
# Büyük harflerden küçük harflere (Türkçe kuralları)
_TO_LOWER = {
    "İ": "i",
    "I": "ı",
}


def tr_lower(s):
    """Türkçe kurallarıyla küçük harfe çevirir (I -> ı, İ -> i)."""
    return "".join(_TO_LOWER.get(ch, ch.lower()) for ch in s)


def tr_upper(s):
    """Türkçe kurallarıyla büyük harfe çevirir (i -> İ, ı -> I)."""
    return "".join(_TO_UPPER.get(ch, ch.upper()) for ch in s)


def _tr_key(word):
    """Sıralama anahtarı: (tip, kod noktası, sıra) üçlüsünün listesi.

    - listede olmayan karakterler (boşluk, noktalama vb.) tip 0 ile listedeki
      tüm karakterlerden önce gelir, kendi aralarında Unicode kod noktasına
      göre sıralanır;
    - Türk alfabesindeki harfler tip 1 ile (harf, sıra) olarak sıralanır;
    - alfabede olmayan diğer karakterler tip 2 ile Unicode kod noktasına göre
      sıralanır.
    """
    key = []
    for ch in tr_lower(word):
        rank = _ALPHABET_INDEX.get(ch)
        if rank is None:
            if ch in _DIGIT_RANK:
                key.append((1, 0, _DIGIT_RANK[ch], ch))
            else:
                key.append((2, ord(ch), 0, ch))
        else:
            key.append((1, rank, rank, ch))
    return key


def tr_sorted(words):
    """Kelimeleri Türk alfabesine göre, harf büyük/küçük farkı gözetmeden sıralar.

    Girdi listesi değiştirilmez; sıralanmış yeni bir liste döner.
    Eşit sayılan kelimeler girdideki sıralarını korur.
    """
    indexed = list(enumerate(words))
    indexed.sort(key=lambda item: _tr_key(item[1]))
    return [word for _, word in indexed]

