_TR_ORDER = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"
_TR_RANK = {ch: i for i, ch in enumerate(_TR_ORDER)}


def tr_lower(s: str) -> str:
    """Türkçe kurallarıyla küçük harfe çevirir (I -> ı, İ -> i)."""
    return "".join(
        {"I": "ı", "İ": "i"}.get(ch, ch.lower()) for ch in s
    )


def tr_upper(s: str) -> str:
    """Türkçe kurallarıyla büyük harfe çevirir (i -> İ, ı -> I)."""
    return "".join(
        {"i": "İ", "ı": "I"}.get(ch, ch.upper()) for ch in s
    )


def _tr_key(word: str) -> list:
    """Sıralama anahtarı.

    - listedeki karakterler: (1, sıra) — listedeki sıraya göre;
    - listede olmayan karakterler: (0, kod noktası) — listedeki tüm
      karakterlerden önce, kendi aralarında Unicode kod noktasına göre.
    """
    key = []
    for ch in tr_lower(word):
        rank = _TR_RANK.get(ch)
        if rank is not None:
            key.append((1, rank))
        else:
            key.append((0, ord(ch)))
    return key


def tr_sorted(words: list) -> list:
    """Kelimeleri Türk alfabesine göre, harf büyük/küçük farkı gözetmeden sıralar.

    Girdi listesi değiştirilmez; sıralanmış yeni bir liste döner.
    Eşit sayılan kelimeler girdideki sıralarını korur (stabil sıralama).
    """
    indexed = list(enumerate(words))
    indexed.sort(key=lambda item: _tr_key(item[1]))
    return [word for _, word in indexed]

